@torch.no_grad()
def copy_megatron_model_to_cpu(models):
    """
    Copy Megatron model parameters to CPU memory (non-destructive copy).
    Unlike offload_megatron_model_to_cpu which moves data, this function creates
    independent copies on CPU while keeping GPU data intact.

    Args:
        models: List of model chunks (DDP-wrapped or unwrapped)

    Returns:
        dict: CPU state containing copied parameters and buffers
    """
    cpu_state = {}

    for model_idx, model_chunk in enumerate(models):
        if isinstance(model_chunk, DDP):
            # Handle DDP-wrapped models
            model_chunk_all_buffers = [model_chunk.buffers, model_chunk.expert_parallel_buffers]
            buffer_states = []

            for buffers in model_chunk_all_buffers:
                buffer_list = []
                for buffer in buffers:
                    buffer_state = {}

                    # Copy parameter data to CPU
                    if buffer.param_data.storage().size() > 0:
                        buffer_state["param_data"] = buffer.param_data.data.cpu().clone().pin_memory()
                    else:
                        buffer_state["param_data"] = buffer.param_data.cpu_data.clone().pin_memory()

                    buffer_list.append(buffer_state)
                buffer_states.append(buffer_list)

            cpu_state[f"model_chunk_{model_idx}"] = {"buffer_states": buffer_states, "is_ddp": True}
        else:
            # Handle non-DDP models (ref module)
            model_state = {}
            for name, param in model_chunk.named_parameters():
                param_state = {"data": param.data.cpu().clone().pin_memory()}
                model_state[name] = param_state

            cpu_state[f"model_chunk_{model_idx}"] = {"model_state": model_state, "is_ddp": False}

    return cpu_state


@torch.no_grad()
def restore_megatron_model_from_cpu(models, cpu_state):
    """
    Restore Megatron model parameters from CPU memory back to GPU.

    Args:
        models: List of model chunks to restore to
        cpu_state: CPU state dict returned from copy_megatron_model_to_cpu
    """
    for model_idx, model_chunk in enumerate(models):
        chunk_key = f"model_chunk_{model_idx}"
        if chunk_key not in cpu_state:
            continue

        chunk_state = cpu_state[chunk_key]

        if chunk_state["is_ddp"] and isinstance(model_chunk, DDP):
            # Restore DDP buffers
            model_chunk_all_buffers = [model_chunk.buffers, model_chunk.expert_parallel_buffers]
            buffer_states = chunk_state["buffer_states"]

            for buffers, buffer_list in zip(model_chunk_all_buffers, buffer_states, strict=False):
                for buffer, buffer_state in zip(buffers, buffer_list, strict=False):
                    # Restore parameter data
                    if "param_data" in buffer_state:
                        if buffer.param_data.storage().size() > 0:
                            buffer.param_data.data.copy_(buffer_state["param_data"].to(buffer.param_data.device))
                        else:
                            buffer.param_data.cpu_data.copy_(buffer_state["param_data"])

        elif not chunk_state["is_ddp"] and not isinstance(model_chunk, DDP):
            # Restore non-DDP models
            model_state = chunk_state["model_state"]
            for name, param in model_chunk.named_parameters():
                if name in model_state:
                    param_state = model_state[name]
                    param.data.copy_(param_state["data"].to(param.device))

def set_current_microbatch(model, microbatch_id):
    """Set the current microbatch."""
    decoder_exists = True
    model_with_decoder = None
    try:
        model_with_decoder = get_attr_wrapped_model(
            model, "decoder", allow_none=False, return_model_obj=True
        )
    except RuntimeError:
        decoder_exists = False
    if decoder_exists and model_with_decoder is not None:
        for layer in model_with_decoder.decoder.layers:
            layer.current_microbatch = microbatch_id
        if hasattr(model_with_decoder, 'mtp'):
            for layer in model_with_decoder.mtp.layers:
                layer.transformer_layer.current_microbatch = microbatch_id


def forward_step_calc_loss(
    model,
    output_tensor,
    loss_func,
    config,
    vp_stage,
    collect_non_loss_data,
    num_microbatches,
    forward_data_store,
    cp_group_size=None,
    is_last_stage=None,
):
    """Calculate the loss and number of tokens for forward_step()"""

    from megatron.core.transformer.multi_token_prediction import MTPLossAutoScaler

    model_vp_stage = getattr(model, "vp_stage", None)
    if vp_stage is not None and model_vp_stage is not None:
        assert (
            vp_stage == model_vp_stage
        ), f"vp_stage ({vp_stage}) doesn't match model_vp_stage ({model_vp_stage})"

    if cp_group_size is None and is_last_stage is None:
        # fallback to parallel state
        cp_group_size = parallel_state.get_context_parallel_world_size()
        is_last_stage = parallel_state.is_pipeline_last_stage(
            ignore_virtual=False, vp_stage=vp_stage
        )
    else:
        assert (
            cp_group_size is not None and is_last_stage is not None
        ), "cp_group_size and is_last_stage must be provided"

    num_tokens = torch.tensor(0, dtype=torch.int)
    if is_last_stage:
        if loss_func is None:
            forward_data_store.append(output_tensor)
        elif not collect_non_loss_data:
            outputs = loss_func(output_tensor)
            if len(outputs) == 3:
                output_tensor, num_tokens, loss_reduced = outputs
                if not config.calculate_per_token_loss:
                    # Protect against division by zero when all tokens are masked
                    #   in a microbatch.
                    output_tensor /= torch.clamp(num_tokens, min=1)
                    output_tensor /= num_microbatches
            else:
                # preserve legacy loss averaging behavior (ie, over the number of microbatches)
                assert len(outputs) == 2
                output_tensor, loss_reduced = outputs
                output_tensor *= cp_group_size
                output_tensor /= num_microbatches
            forward_data_store.append(loss_reduced)
        else:
            data = loss_func(output_tensor, non_loss_data=True)
            forward_data_store.append(data)

    if config.timers is not None:
        config.timers('forward-compute').stop()

    # Set the loss scale for the auxiliary loss of the MoE layer.
    # Since we use a trick to do backward on the auxiliary loss, we need to set the scale
    # explicitly.
    if hasattr(config, 'num_moe_experts') and config.num_moe_experts is not None:
        # Calculate the loss scale based on the grad_scale_func if available, else default to 1.
        loss_scale = (
            config.grad_scale_func(torch.ones(1, device=output_tensor.device))
            if config.grad_scale_func is not None
            else torch.ones(1, device=output_tensor.device)
        )
        # Set the loss scale
        if config.calculate_per_token_loss:
            MoEAuxLossAutoScaler.set_loss_scale(loss_scale)
        else:
            MoEAuxLossAutoScaler.set_loss_scale(loss_scale * cp_group_size / num_microbatches)

    # Set the loss scale for Multi-Token Prediction (MTP) loss.
    if hasattr(config, 'mtp_num_layers') and config.mtp_num_layers is not None:
        # Calculate the loss scale based on the grad_scale_func if available, else default to 1.
        loss_scale = (
            config.grad_scale_func(torch.ones(1, device=output_tensor.device))
            if config.grad_scale_func is not None
            else torch.ones(1, device=output_tensor.device)
        )
        # Set the loss scale
        if config.calculate_per_token_loss:
            MTPLossAutoScaler.set_loss_scale(loss_scale)
        else:
            MTPLossAutoScaler.set_loss_scale(loss_scale / num_microbatches)

    return output_tensor, num_tokens

            assert (
                not self.config.flash_decode
            ) or inference_context.is_static_batching(), (
                "Flash decode is only applicable to static batching."
            )
            # Flash decoding uses precomputed cos and sin for RoPE
            if self.config.flash_decode:
                rotary_pos_cos, rotary_pos_sin = self.rotary_pos_emb_cache.setdefault(
                    inference_context.max_sequence_length,
                    self.rotary_pos_emb.get_cos_sin(inference_context.max_sequence_length),
                )
            elif use_flash_infer_fused_rope:
                assert not self.mtp_process, "MTP not tested with flashinfer_fused_rope"
                rotary_pos_cos_sin = self.rotary_pos_emb_cache.setdefault(
                    inference_context.max_sequence_length,
                    torch.cat(
                        self.rotary_pos_emb.get_cos_sin(inference_context.max_sequence_length),
                        -1,
                    ),
                )
        else:
            rotary_seq_len = self.rotary_pos_emb.get_rotary_seq_len(
                inference_context, self.decoder, decoder_input, self.config, packed_seq_params
            )
            rotary_pos_emb = self.rotary_pos_emb(
                rotary_seq_len,
                packed_seq=packed_seq_params is not None
                and packed_seq_params.qkv_format == 'thd',
                cp_group=packed_seq_params.cp_group if packed_seq_params is not None else None,
            )
    elif self.position_embedding_type == 'yarn':
        if self.training or not self.config.flash_decode:
            rotary_seq_len = self.rotary_pos_emb.get_rotary_seq_len(
                inference_context, self.decoder, decoder_input, self.config, packed_seq_params
            )
            rotary_pos_emb, _ = self.rotary_pos_emb(
                rotary_seq_len,
                packed_seq=packed_seq_params is not None
                and packed_seq_params.qkv_format == 'thd',
                cp_group=packed_seq_params.cp_group if packed_seq_params is not None else None,
            )
        else:
            raise NotImplementedError(
                "Flash decoding uses precomputed cos and sin for RoPE, not implemented in "
                "YarnRotaryEmbedding yet."
            )
    elif self.position_embedding_type == 'mrope' and not self.config.multi_latent_attention:
        if self.training or not self.config.flash_decode:
            rotary_pos_emb = self.rotary_pos_emb(
                position_ids,
                self.mrope_section,
                cp_group=packed_seq_params.cp_group if packed_seq_params is not None else None,
            )
        else:
            # Flash decoding uses precomputed cos and sin for RoPE
            raise NotImplementedError(
                "Flash decoding uses precomputed cos and sin for RoPE, not implemented in "
                "MultimodalRotaryEmbedding yet."
            )

    if (
        in_inference_mode
        and (
            (
                self.config.cuda_graph_impl == "local"
                and CudaGraphScope.full_iteration not in self.config.cuda_graph_scope
            )
            or self.config.flash_decode
        )
        and inference_context.is_static_batching()
    ):
        current_batch_size = input_ids.shape[0]
        sequence_len_offset = torch.tensor(
            [inference_context.sequence_len_offset] * current_batch_size,
            dtype=torch.int32,
            device=torch.cuda.current_device(),
        )
    else:
        sequence_len_offset = None

    if in_inference_mode:
        # Clear the outputs for padding tokens when using dynamic batching with
        # quantization scales to avoid corrupting amax calculations
        if inference_context.is_dynamic_batching() and is_using_quantization_scales(
            self.config
        ):
            decoder_input[inference_context.padding_slice] = 0.0

        # Wrap decoder_input to allow the decoder (TransformerBlock) to delete the
        # reference held by this caller function, enabling early garbage collection for
        # inference. Skip wrapping if decoder_input is logged after decoder completion.
        if not has_config_logger_enabled(self.config):
            decoder_input = WrappedTensor(decoder_input)

    preproc_output = (
        decoder_input,
        rotary_pos_emb,
        rotary_pos_cos,
        rotary_pos_sin,
        sequence_len_offset,
        padding_mask,
    )
    if rotary_pos_cos_sin is not None:
        # only in the case of flashinfer fused rope will we
        # return this extra tensor
        # this is for backwards compatibility with
        # legacy unit tests, which break if you
        # return a 6 tuple instead of 5.
        preproc_output += (rotary_pos_cos_sin,)

    return preproc_output

def preprocess_for_fine_grained_offloading(self):
    """Preprocess for fine-grained activation offloading."""
    off_interface.init_chunk_handler(
        vp_size=self.config.virtual_pipeline_model_parallel_size,
        vp_stage=self.vp_stage,
        min_offloaded_tensor_size=self.config.min_offloaded_tensor_size,
    )
    if self.disable_param_offloading:

            local_path=local_path, hdfs_path=hdfs_path, global_step=global_step, max_ckpt_to_keep=max_ckpt_to_keep
        )
        torch.distributed.barrier()
        if self._is_offload_param:
            offload_megatron_model_to_cpu(self.module)

    def load_checkpoint(
        self, local_path: str, hdfs_path: Optional[str] = None, del_local_after_load: bool = True, **kwargs
    ) -> None:
        """
        Load model, optimizer, and scheduler states from a checkpoint.

        Args:
            local_path: Local filesystem path of the checkpoint.
            hdfs_path: Optional HDFS path where checkpoint is stored.
            del_local_after_load: Whether to delete local copy after loading.
        """
        if self._is_offload_param:
            load_megatron_model_to_gpu(self.module)
        self.checkpoint_mananager.load_checkpoint(
            local_path=local_path, hdfs_path=hdfs_path, del_local_after_load=del_local_after_load
        )
        if self._is_offload_param:
            offload_megatron_model_to_cpu(self.module)
        if self._is_offload_optimizer:
            offload_megatron_optimizer(self.optimizer)

    def forward_backward_batch(self, data: TensorDict, loss_function: Callable, forward_only=False) -> Any:
        self._distillation_use_topk_active = tu.get_non_tensor_data(data, key="distillation_use_topk", default=False)
        tu.assign_non_tensor(data, sp_size=self.engine_config.context_parallel_size)

        # compute num_tokens in global batch for loss normalization
        batch_num_tokens = data["loss_mask"].sum().to(get_device_id())
        torch.distributed.all_reduce(
            batch_num_tokens, op=torch.distributed.ReduceOp.SUM, group=self.get_data_parallel_group()
        )
        tu.assign_non_tensor(data, batch_num_tokens=batch_num_tokens.item())
        tu.assign_non_tensor(data, dp_size=self.get_data_parallel_size())

        # BSHD path only: pad every micro-batch to the mini-batch's global max seq_len so the
        # padded `s_q` is shared -> cuDNN plan built once per shape. Raw (unaligned)
        # max; TP/CP/FP8 alignment is applied inside preprocess_bshd_engine.
        pad_bshd_to_minibatch_max = self.engine_config.pad_bshd_to_minibatch_max
        global_max_seqlen = None
        if pad_bshd_to_minibatch_max and not self.engine_config.use_remove_padding and "input_ids" in data.keys():
            input_ids_for_max = data["input_ids"]
            if input_ids_for_max.is_nested:
                global_max_seqlen = int(input_ids_for_max.offsets().diff().max().item())

        vpp_size = mpu.get_virtual_pipeline_model_parallel_world_size()
        if vpp_size is not None and vpp_size > 1:
            num_batches_divided_by = self.tf_config.microbatch_group_size_per_vp_stage
        else:
            num_batches_divided_by = None

        micro_batches, indices = prepare_micro_batches(
            data=data,
            dp_group=self.get_data_parallel_group(),
            num_batches_divided_by=num_batches_divided_by,
            same_micro_num_in_dp=True,
            min_num_micro_batch=None,
        )

        if num_batches_divided_by is not None:
            assert len(micro_batches) % num_batches_divided_by == 0, (
                f"micro_batches {micro_batches} must be divisible by num_batches_divided_by "
                f"{num_batches_divided_by} for megatron backend"
            )

        # compute input shapes for pp stages
        n_micro_batch = len(micro_batches)

        for micro_batch in micro_batches:
            tu.assign_non_tensor(micro_batch, num_micro_batch=n_micro_batch)
            if global_max_seqlen is not None:
                tu.assign_non_tensor(micro_batch, forced_max_seqlen=global_max_seqlen)

        forward_backward_func = get_forward_backward_func()

        postprocess_micro_batch_func = partial(
            self.postprocess_micro_batch_func,
            forward_only=forward_only,
            loss_function=loss_function,
        )

        tu.assign_non_tensor(data, num_micro_batch=n_micro_batch)

        forward_step = partial(
            self.forward_step,
            logits_processor_func=loss_function,
            postprocess_micro_batch_func=postprocess_micro_batch_func,
        )

        enable_routing_replay = tu.get_non_tensor_data(data, key="enable_routing_replay", default=False)

        if enable_routing_replay:
            # Set to REPLAY mode: for R3 mode or actor update phase in R2 mode
            RouterReplay.set_global_router_replay_action(RouterReplayAction.REPLAY_FORWARD)
            if forward_only and self.engine_config.router_replay.mode == "R2":
                # In R2 mode, forward_only calls (e.g., compute_log_probs) need to record routing information
                RouterReplay.set_global_router_replay_action(RouterReplayAction.RECORD)

        # batch should be a list of batches inside micro-batches
        batch_generator = make_batch_generator(micro_batches, vpp_size=len(self.module))

        # TODO: we may use the new schedule instead
        # for flash-attn: (seq_len, batch_size, hidden_size) = (mbs*seq_len, 1, hidden_size)
        losses_reduced = forward_backward_func(
            forward_step_func=forward_step,
            data_iterator=batch_generator,
            model=self.module,
            num_microbatches=n_micro_batch,
            seq_length=1,  # the communication shape is obtained via p2p comm
            micro_batch_size=1,  # the communication shape is obtained via p2p comm
            forward_only=forward_only,
        )

        if self.model_config.mtp.enable and mpu.is_pipeline_last_stage(ignore_virtual=True):
            # All CP ranks must participate in the all_reduce inside get_megatron_mtp_loss,
            # because save_loss_to_tracker uses avg_group=DP+CP group.
            # Only collect metrics on the src rank afterward.
            metrics = get_megatron_mtp_loss(n_micro_batch)
            if self.is_mp_src_rank_with_outputs():
                if "metrics" not in losses_reduced[0]:
                    losses_reduced[0]["metrics"] = {}
                losses_reduced[0]["metrics"].update(metrics)

        if RouterReplayHelper.is_r2_record_action(self.tf_config):
            if self.tf_config.virtual_pipeline_model_parallel_size is not None:
                # config = self.actor_module[0].module.module.config
                vp_size = len(self.module)
                microbatch_group_size_per_vp_stage = self.tf_config.microbatch_group_size_per_vp_stage
                bs = n_micro_batch
                topk_idx_td = reorder_and_merge_vpp_layers(
                    self.mini_layer_topk_idx_list, bs, vp_size, microbatch_group_size_per_vp_stage
                )
            else:
                tensors = [tensor for nt in self.mini_layer_topk_idx_list for tensor in nt.unbind()]
                topk_idx_td = torch.nested.as_nested_tensor(tensors, layout=torch.jagged)
            self.mini_layer_topk_idx_list = []

            layers_topk_idx = pp_gather(topk_idx_td.to(torch.uint8), self.tf_config)
            use_dynamic_bsz = tu.get_non_tensor_data(data=data, key="use_dynamic_bsz", default=True)
            if use_dynamic_bsz and indices is not None:
                layers_topk_idx = restore_dynamic_batch(layers_topk_idx, indices)

        output = {}
        if mpu.is_pipeline_last_stage(ignore_virtual=True):
            output = postprocess_batch_func(output_lst=losses_reduced, indices=indices, data=data)
            if RouterReplayHelper.is_r2_record_action(self.tf_config):
                output["model_output"]["routed_experts"] = layers_topk_idx
        if enable_routing_replay:
            RouterReplay.clear_global_indices()
            RouterReplay.clear_global_router_replay_action()
        return output

    def get_per_tensor_param(self, base_sync_done=False, **kwargs):
        peft_config = None
        non_merge_lora_sync = self.peft_cls is not None and not self.model_config.lora.get("merge", False)
        adapter_only = base_sync_done and non_merge_lora_sync
        if non_merge_lora_sync:
            peft_config = build_peft_config_for_vllm(self.model_config.lora)
        # when lora adapter only, we only load adapter weights when base sync is done, otherwise load all weights
        load_megatron_model_to_gpu(self.module, load_grad=False, load_frozen_params=not adapter_only)
        if self.vanilla_bridge:
            per_tensor_param = self.bridge.export_weights(self.module)
        elif adapter_only:
            per_tensor_param = self.bridge.export_adapter_weights(self.module)
        else:
            per_tensor_param = (
                self.bridge.export_hf_weights(self.module, merge_adapter_weights=False)
                if non_merge_lora_sync
                else self.bridge.export_hf_weights(self.module)
            )
            if non_merge_lora_sync:
                per_tensor_param = add_base_layer_suffix(
                    per_tensor_param, model_type=self.model_config.hf_config.model_type
                )

        # QAT: process weights through QATWeightExporter for quantized weight sync to vLLM
        if self._qat_enabled:
            from verl.utils.modelopt import export_qat_weights

            per_tensor_param = export_qat_weights(per_tensor_param, self.module, self._qat_config.mode, self.bridge)

        return per_tensor_param, peft_config

    def disable_adapter(self) -> ContextManager:
        return self.peft_cls.disable_adapter(self.module)

    def forward_step(self, batch_iter, model, logits_processor_func, postprocess_micro_batch_func):
        raise NotImplementedError("forward_step must be implemented in subclass")

    def postprocess_micro_batch_func(self, output, data: TensorDict, forward_only: bool, loss_function):
        raise NotImplementedError("postprocess_micro_batch_func must be implemented in subclass")


class EngineEvalModeCtx(BaseEngineCtx):
    def __init__(self, engine: MegatronEngine, **kwargs):
        super().__init__(engine=engine, mode="eval", **kwargs)

    def __enter__(self):
        assert isinstance(self.engine, MegatronEngine)
        super().__enter__()
        # mcore module is a list of model chunk in each vpp stage
        for module in self.engine.module:
            module.eval()

    def __exit__(self, exc_type, exc_value, traceback):
        assert isinstance(self.engine, MegatronEngine)
        super().__exit__(exc_type, exc_value, traceback)


class EngineTrainModeCtx(BaseEngineCtx):
    def __init__(self, engine: MegatronEngine, **kwargs):
        super().__init__(engine=engine, mode="train", **kwargs)

    def __enter__(self):
        assert isinstance(self.engine, MegatronEngine)
        super().__enter__()
        # mcore module is a list of model chunk in each vpp stage
        for module in self.engine.module:
            module.train()

    def __exit__(self, exc_type, exc_value, traceback):
        assert isinstance(self.engine, MegatronEngine)
        if self.zero_grad_on_exit or exc_type is not None:
            self.engine.optimizer_zero_grad()
        super().__exit__(exc_type, exc_value, traceback)


@EngineRegistry.register(model_type="language_model", backend="megatron")
class MegatronEngineWithLMHead(MegatronEngine):
    def prepare_model_inputs(self, batch: TensorDict):
        input_ids = batch["input_ids"]
        loss_mask = batch["loss_mask"].to(bool)
        multi_modal_inputs = extract_multi_modal_inputs(batch.get("multi_modal_inputs", []))

        routed_experts = batch.get("routed_experts", None)

        return {
            "input_ids": input_ids,
            "attention_mask": batch.get("attention_mask", None),
            "loss_mask": loss_mask,
            "multi_modal_inputs": multi_modal_inputs,
            "routed_experts": routed_experts,
        }

    def prepare_model_outputs(self, output: dict, data: TensorDict):
        return output

    def _lm_head_logits_processor(
        self,
        logits,
        label,
        temperature,
        *,
        calculate_sum_pi_squared: bool,
        calculate_entropy: bool,
        distillation_use_topk: bool,
        distillation_only: bool,
        logits_processor_func: Callable,
        batch: TensorDict,
        data_format: str,
    ):
        assert logits.shape[:2] == label.shape[:2]
        # avoid non-positive temperature such as padding
        temperature[temperature <= 0] = 1e-8
        assert torch.all(temperature > 0).item(), f"temperature tensor must be positive. Got {temperature}"
        logits.div_(temperature.unsqueeze(dim=-1).to(logits.dtype))
        ret = {}
        # sum_pi_squared is non-destructive — must run before vocab_parallel_entropy.
        if calculate_sum_pi_squared:
            ret["sum_pi_squared"] = vocab_parallel_sum_pi_squared(logits)
        if calculate_entropy:
            logits_bak = logits.clone()
            # # disable the hint until the fused_kernel is optimized for triton>=3.3
            # if torch.distributed.get_rank() == 0:
            #     logger.warning_once(
            #         "For memory-efficient computation, enable fused kernels via "
            #         "`actor_rollout_ref.model.use_fused_kernels=True`. "
            #         "The current `clone()` operation ensures correctness but increases memory usage."
            #     )
            if self.engine_config.entropy_from_logits_with_chunking:
                entropy = vocab_parallel_entropy_with_chunking(
                    logits,
                    chunk_size=self.engine_config.entropy_from_logits_chunk_size,
                )
            else:
                entropy = vocab_parallel_entropy(logits)

            ret["entropy"] = entropy
        else:
            logits_bak = logits

        # logits_processor_func return tensors with shape (1, total_nnz/cp_size)
        if distillation_use_topk:
            ret.update(logits_processor_func(student_logits=logits_bak, data=batch, data_format=data_format))
        if not distillation_only:
            ret["log_probs"] = vocab_parallel_log_probs_from_logits(logits_bak, label)

        **model_kwargs,
    )

    if post_process and logits_processor is not None:
        args = {
            k: preprocess_thd_engine(
                v,
                pre_process=True,
                need_roll=(k == "label"),
                use_fp8_padding=use_fp8_padding,
                local_cp_size=local_cp_size,
                pad_to_length_bucket=pad_to_length_bucket,
                cp_layout=cp_layout,
            )[0]
            for k, v in logits_processor_args.items()
        }
        output_dict = logits_processor(output_orig, **args)
        output = {
            k: postprocess_thd_engine(
                v,
                packed_seq_params,
                input_ids,
                batch_size,
                post_process=post_process,
                local_cp_size=local_cp_size,
                cp_layout=cp_layout,
            )
            for k, v in output_dict.items()
        }
    else:
        output = postprocess_thd_engine(
            output_orig,
            packed_seq_params,
            input_ids,
            batch_size,
            post_process=post_process,
            local_cp_size=local_cp_size,
            cp_layout=cp_layout,
        )
else:
    """
    data_format: "thd" or "bshd", default is "thd",
    why we need this?
        for some new models, GPT-OSS, the thd format is not supported, so we need to use the bshd format.
    When using the bshd format, we have to add paddings to the input_ids to meet the longest sequence length, 
    so it is recommended to disable dynamic batch size and set batch size to 1
    """
    assert local_cp_size is None, "dynamic_CP is not supported for bshd format"

    input_ids_bshd, attention_mask_bshd, position_ids_bshd = preprocess_bshd_engine(
        input_ids,
        pre_process=pre_process or (post_process and mtp_enable_train),
        use_fp8_padding=use_fp8_padding,
        forced_max_seqlen=forced_max_seqlen,
    )

    if mtp_enable_train and post_process:
        args = {}
        # Use input_ids sequence length to ensure label and loss_mask alignment
        input_ids_offsets = input_ids.offsets()
        input_ids_lengths = input_ids_offsets.diff().tolist()
        response_attention_mask = logits_processor_args.get("response_attention_mask", None)

        for k in ["label", "loss_mask"]:
            v = logits_processor_args[k]
            if k == "loss_mask":
                v = _build_mtp_loss_mask_nested(v, input_ids_lengths, response_attention_mask)
            else:
                v = _convert_to_nested_tensor(v, input_ids_lengths)
            logits_processor_args[k] = v
            args[k] = preprocess_bshd_engine(
                v,
                pre_process=True,
                need_roll=True,
                use_fp8_padding=use_fp8_padding,
                forced_max_seqlen=forced_max_seqlen,
            )[0]
        model_kwargs["labels"] = args["label"].contiguous()
        model_kwargs["loss_mask"] = args["loss_mask"].contiguous()

    if logits_processor_args and "loss_mask" in logits_processor_args:
        logits_processor_args.pop("loss_mask")
    if logits_processor_args and "response_attention_mask" in logits_processor_args:
        logits_processor_args.pop("response_attention_mask")

    # For VLM model, need to pass bshd format `input_ids` and `attention_mask`.
    if vision_model:
        input_ids_bshd, attention_mask = build_vlm_attn_mask_bshd(
            input_ids, batch_size, pad_token_id, forced_max_seqlen=forced_max_seqlen
        )
    else:
        attention_mask = attention_mask_bshd

    output_orig = model(
        input_ids=input_ids_bshd,
        attention_mask=attention_mask,
        position_ids=None if vision_model else position_ids_bshd,
        **model_kwargs,
    )
    if post_process and logits_processor is not None:
        args = {
            k: preprocess_bshd_engine(
                v,
                pre_process=True,
                need_roll=(k == "label"),
                use_fp8_padding=use_fp8_padding,
                forced_max_seqlen=forced_max_seqlen,
            )[0]
            for k, v in logits_processor_args.items()
        }
        output_dict = logits_processor(output_orig, **args)
        output = {
            k: postprocess_bshd_engine(v, attention_mask_bshd, post_process=post_process)
            for k, v in output_dict.items()
        }
    else:
        output = postprocess_bshd_engine(output_orig, attention_mask_bshd, post_process=post_process)

if value_model and post_process:
    # output = output[..., 0]
    # while using nested tensor, the advanced indexing operation above will result in an error at backward, i.e.
    # ValueError: NestedTensor _nested_select_backward_default(grad_output: t, self: jt_all, dim: any, index: any)
    # so we use `squeeze` to remove the last dimension
    output = output.squeeze(-1)

return output

def _build_megatron_module(self):
    from verl.utils.megatron_utils import McoreModuleWrapperConfig, make_megatron_module
    from verl.utils.model import print_model_size

    if self.engine_config.forward_only:
        wrap_with_ddp = False
    else:
        wrap_with_ddp = True

    wrap_config = McoreModuleWrapperConfig(
        is_value_model=self.is_value_model,
        wrap_with_ddp=wrap_with_ddp,
        use_distributed_optimizer=self.engine_config.use_distributed_optimizer,
        use_megatron_fsdp=self.engine_config.use_megatron_fsdp,
    )
    override_ddp_config = self._resolve_override_ddp_config()

    module, updated_tf_config = make_megatron_module(
        wrap_config=wrap_config,
        tf_config=self.tf_config,
        hf_config=self.model_config.hf_config,
        bridge=self.bridge,
        provider=self.provider,
        override_model_config=self.engine_config.override_mcore_model_config,
        override_ddp_config=override_ddp_config,
        peft_cls=self.peft_cls,
        peft_config=self.model_config.get("lora", None),
    )
    self.tf_config = updated_tf_config
    print(f"module: {len(module)}")

    if self.engine_config.use_dist_checkpointing:
        load_mcore_dist_weights(
            module, self.engine_config.dist_checkpointing_path, is_value_model=self.is_value_model
        )
    else:
        if self.vanilla_bridge:
            self.bridge.load_weights(module, self.model_config.local_path)
        else:
            allowed_mismatched_params = []
            if self.is_value_model:
                allowed_mismatched_params = ["output_layer.weight"]
            self.bridge.load_hf_weights(
                module, self.model_config.local_path, allowed_mismatched_params=allowed_mismatched_params
            )

    if torch.distributed.get_rank() == 0:
        print_model_size(module[0])

    if self.enable_routing_replay:
        print(f"routing replay layers: {len(RouterReplay.router_instances)}")

    return module

def _maybe_enable_fused_kernels(self):
    if not self.engine_config.use_fused_kernels:
        return

    if self.is_value_model or self.model_config.mtp.enable:
        logger.warning_once(
            "Fused kernels are not supported for value models or when MTP is enabled in Megatron engine; disabling."
        )
        self.engine_config.use_fused_kernels = False
        return

    from verl.models.mcore.model_forward_fused import patch_fused_forward

    for model in self.module:
        patch_fused_forward(model)

def _build_optimizer(self):
    from verl.utils.megatron.optimizer import get_megatron_optimizer, init_megatron_optim_config

    optim_config_megatron = init_megatron_optim_config(
        self.optimizer_config,
        use_distributed_optimizer=self.engine_config.use_distributed_optimizer,
        fp16=self.param_dtype == torch.float16,
        bf16=self.param_dtype == torch.bfloat16,
    )
    optimizer = get_megatron_optimizer(model=self.module, config=optim_config_megatron)

    # are set for all params so the optimizer can use them.
    for model_module in model:
        for param in model_module.parameters():
            tensor_parallel.set_defaults_if_not_set_tensor_model_parallel_attributes(param)

    # Print number of parameters.
    if mpu.get_data_parallel_rank() == 0:
        print(
            " > number of parameters on (tensor, pipeline) model parallel rank ({}, {}): {}".format(
                mpu.get_tensor_model_parallel_rank(),
                mpu.get_pipeline_model_parallel_rank(),
                sum([sum([p.nelement() for p in model_module.parameters()]) for model_module in model]),
            ),
            flush=True,
        )

    # GPU allocation.
    if transformer_config is None or (not transformer_config.use_cpu_initialization):
        for model_module in model:
            model_module.to(f"{get_device_name()}:{get_device_id()}")

    # Fp16 conversion.
    config: TransformerConfig = get_model_config(model[0])
    config.fp8 = None
    tfconfig: TransformerConfig = model[0].config
    if config.fp16 or config.bf16:  # the ModelParallelConfig in GPTModel
        model = [Float16Module(config, model_module) for model_module in model]

    if wrap_with_ddp:
        # Default to reducing grads in fp32. When the precision-aware optimizer is
        # opted into with a sub-fp32 `main_grads_dtype`, the engine injects
        # `grad_reduce_in_fp32=False` via `override_ddp_config` so the DDP grad
        # bucket dtype matches the optimizer's grad buffer. User overrides still win.
        ddp_models = []
        ddp_config_dict = {
            "use_distributed_optimizer": use_distributed_optimizer,
            "grad_reduce_in_fp32": True,
            "overlap_grad_reduce": False,
        }
        if override_ddp_config is not None:
            ddp_config_dict.update(override_ddp_config)
        ddp_config = DistributedDataParallelConfig(**ddp_config_dict)
        for model_chunk_idx, model_chunk in enumerate(model):
            ddp_model = DDP(
                config=tfconfig,
                module=model_chunk,
                disable_bucketing=(model_chunk_idx > 0),
                ddp_config=ddp_config,
            )
            ddp_models.append(ddp_model)
        model = ddp_models
        # # Broadcast params from data parallel src rank to other data parallel ranks.
        # # if args.data_parallel_random_init:
        for model_module in model:
            model_module.broadcast_params()
    return model


def get_hf_rope_theta(hf_config: PretrainedConfig) -> float:
    """Return RoPE base frequency theta.

    Most configs expose ``rope_theta`` on the root. Newer models (e.g. Qwen3 in transformers>=5) store it under
    ``rope_parameters["rope_theta"]``, optionally nested per attention pattern when ``rope_parameters`` maps names
    to parameter dicts.
    """
    # For transformers <= 4.57.6
    if hasattr(hf_config, "rope_theta"):
        return hf_config.rope_theta
    if hasattr(hf_config, "text_config") and hasattr(hf_config.text_config, "rope_theta"):
        return hf_config.text_config.rope_theta

    # For transformers >= 5.0.0, check rope_parameters dict (optionally nested) for rope_theta
    rp = None
    if hasattr(hf_config, "rope_parameters"):
        rp = hf_config.rope_parameters
    elif hasattr(hf_config, "text_config") and hasattr(hf_config.text_config, "rope_parameters"):
        rp = hf_config.text_config.rope_parameters
    if isinstance(rp, dict):
        if "rope_theta" in rp:
            return rp["rope_theta"]
        for v in rp.values():
            if isinstance(v, dict) and "rope_theta" in v:
                return v["rope_theta"]
    raise AttributeError(
        f"{type(hf_config).__name__} has no rope_theta and no rope_parameters['rope_theta'] — "
        "cannot determine RoPE base."
    )


@dataclass
class McoreModuleWrapperConfig:
    """Configuration for Mcore module wrapper."""

    is_value_model: bool = False
    share_embeddings_and_output_weights: bool = False
    wrap_with_ddp: bool = True
    use_distributed_optimizer: bool = True
    use_megatron_fsdp: bool = False


def make_megatron_module(
    wrap_config: McoreModuleWrapperConfig,
    tf_config: TransformerConfig,
    hf_config: PretrainedConfig,
    bridge: Any = None,
    provider: Any = None,
    override_model_config: dict[str, Any] = None,
    override_ddp_config: dict[str, Any] = None,
    peft_cls: Any = None,
    peft_config: Any = None,
):
    from verl.models.mcore.config_converter import get_hf_rope_theta

    hf_config.rope_theta = get_hf_rope_theta(hf_config)

    if override_model_config is None:
        override_model_config = {}

    if bridge is not None:
        if provider is None:
            from verl.models.mcore.mbridge import freeze_moe_router, make_value_model

            value_model_hook = make_value_model
        else:
            from verl.models.mcore.bridge import freeze_moe_router, make_value_model

            hidden_size = (
                hf_config.text_config.hidden_size if hasattr(hf_config, "text_config") else hf_config.hidden_size
            )
            value_model_hook = make_value_model(hidden_size, provider.sequence_parallel)

        post_model_creation_callbacks = []
        if wrap_config.is_value_model:
            post_model_creation_callbacks.append(value_model_hook)
        if override_model_config.get("moe_config", {}).get("freeze_moe_router", False):
            post_model_creation_callbacks.append(freeze_moe_router)
        if provider is not None:
            from megatron.bridge.peft.utils import create_peft_hook, load_peft_adapter_checkpoint
            from megatron.bridge.training.utils.config_utils import create_ddp_config

    # if submodules.mlp is not a ModuleSpec,we dont have to handle passing additional kwargs
    if isinstance(submodules.mlp, ModuleSpec):
        if submodules.mlp.module in (MoELayer, GroupedMLP, TEGroupedMLP, SequentialMLP):
            additional_mlp_kwargs["pg_collection"] = pg_collection
        elif submodules.mlp.module == MLP:
            assert hasattr(
                pg_collection, 'tp'
            ), 'TP process group is required for MLP in TransformerLayer'
            additional_mlp_kwargs["tp_group"] = pg_collection.tp
        elif TEFusedMLP is not None and submodules.mlp.module == TEFusedMLP:
            assert hasattr(
                pg_collection, 'tp'
            ), 'TP process group is required for TEFusedMLP in TransformerLayer'
            additional_mlp_kwargs["tp_group"] = pg_collection.tp
        else:
            log_single_rank(
                logger,
                logging.WARNING,
                f"Unknown MLP type: {type(submodules.mlp)}. Using default kwargs.",
            )
    self.mlp = build_module(submodules.mlp, config=self.config, **additional_mlp_kwargs)
    if hasattr(self.mlp, 'set_layer_number'):
        self.mlp.set_layer_number(self.layer_number)

    # [Module 9: BiasDropoutFusion]
    self.mlp_bda = build_module(submodules.mlp_bda)

    self.is_moe_layer = isinstance(self.mlp, MoELayer)

    self.recompute_input_layernorm = False
    self.recompute_pre_mlp_layernorm = False
    self.recompute_mlp = False
    if self.config.recompute_granularity == 'selective':
        if "layernorm" in self.config.recompute_modules:
            if not isinstance(self.input_layernorm, IdentityOp):
                self.recompute_input_layernorm = True
                if self.config.fp8 or self.config.fp4:
                    self.self_attention.set_for_recompute_input_layernorm()

            def can_recompute_pre_mlp_layernorm_for_cudagraph():
                if (
                    not self.is_moe_layer
                    or CudaGraphScope.moe_router not in self.config.cuda_graph_scope
                    or self.config.cuda_graph_impl == "local"
                ):
                    # Not a MoE layer, or not capturing the router part.
                    return True
                if (
                    self.config.moe_shared_expert_intermediate_size is not None
                    and self.config.moe_shared_expert_overlap
                ):
                    # If shared expert overlap is used, we cannot make the pre-mlp layernorm
                    # recomputation, because the shared expert takes the layernorm output as
                    # input, and it is outside of the CUDA graph scope.
                    log_single_rank(
                        logger,
                        logging.WARNING,
                        "pre_mlp_layernorm recompute is not supported with moe router "
                        "cudagraph + shared expert overlap. Disabling pre_mlp_layernorm "
                        "recompute.",
                    )
                    return False
                if CudaGraphScope.moe_preprocess in self.config.cuda_graph_scope and (
                    self.config.moe_token_dispatcher_type == "alltoall"
                    or self.config.moe_latent_size
                ):
                    # Only when capturing the preprocess part and using alltoall token
                    # dispatcher or latent MoE can we make the pre-mlp layernorm recomputation.
                    # Because in other cases the layernorm output returns directly as one of the
                    # outputs of the cudagraph, which will be allocated a static buffer, thus
                    # not able to be released.
                    return True
                log_single_rank(
                    logger,
                    logging.WARNING,
                    "pre_mlp_layernorm recompute is only supported with moe router + "
                    "preprocess cudagraph will alltoall token dispatcher or latent MoE. "
                    "Disabling pre_mlp_layernorm recompute.",
                )
                return False

            if (
                not isinstance(self.pre_mlp_layernorm, IdentityOp)
                and can_recompute_pre_mlp_layernorm_for_cudagraph()
            ):
                self.recompute_pre_mlp_layernorm = True
                if self.config.fp8 or self.config.fp4:
                    if isinstance(self.mlp, MoELayer):
                        self.mlp.set_for_recompute_pre_mlp_layernorm()
                    else:
                        from megatron.core.extensions.transformer_engine import (
                            set_save_original_input,
                        )

                        set_save_original_input(self.mlp.linear_fc1)
        if "mlp" in self.config.recompute_modules:
            if not self.is_moe_layer:
                self.recompute_mlp = True
    self.offload_attn_norm = (
        self.config.fine_grained_activation_offloading
        and "attn_norm" in self.config.offload_modules
        and not isinstance(self.input_layernorm, IdentityOp)
    )
    self.offload_mlp_norm = (
        self.config.fine_grained_activation_offloading
        and "mlp_norm" in self.config.offload_modules
        and not isinstance(self.pre_mlp_layernorm, IdentityOp)
    )

    # @jcasper how should we handle nvfuser?
